  async function fetchData() {
    try {
      const response = await fetch('https://api.example.com/data');
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }
      const data = await response.json();
      return data;
    } catch (error) {
      console.error("Error fetching data:", error.message);
      return null;
    }
  }

  fetchData().then(data => {
    if (data) {
      console.log("Data fetched successfully:", data);
    }
  }).catch(error => {
    console.error("Failed to fetch data:", error.message);
  });
</script>

</body>
</html>
```

### Explanation:
- **async/await**: This allows you to perform asynchronous operations.
- **Error Handling**: The `try-catch` block handles HTTP errors by catching the `Response` object and throwing an error if the request fails.
- **JSON Parsing**: The response is parsed using `response.json()`.

